import{_ as e,o as a,c as s,a2 as o}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"Ask questions about your data","description":"","frontmatter":{"title":"Ask questions about your data"},"headers":[],"relativePath":"docs/getting-started/ask-questions.md","filePath":"docs/getting-started/ask-questions.md","lastUpdated":1790394058000}'),n={name:"docs/getting-started/ask-questions.md"};function r(i,t,u,c,d,l){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="ask-questions-about-your-data" tabindex="-1">Ask questions about your data <a class="header-anchor" href="#ask-questions-about-your-data" aria-label="Permalink to &quot;Ask questions about your data&quot;">​</a></h1><p>Alongside Recipes, every project has a chat panel where you can ask questions in plain language and get answers grounded in your own data.</p><h2 id="asking-a-question" tabindex="-1">Asking a question <a class="header-anchor" href="#asking-a-question" aria-label="Permalink to &quot;Asking a question&quot;">​</a></h2><p>Type your question into the chat box and press Enter. OrbySystems streams its response back, and you can interrupt with Stop at any time if you want to redirect it. Your recent questions are kept in history so you can recall and reuse them.</p><p>You can ask things like:</p><ul><li>&quot;How much did I spend on restaurants last quarter?&quot;</li><li>&quot;What&#39;s my portfolio&#39;s return this year?&quot;</li><li>&quot;Show me every transaction linked to my car loan.&quot;</li></ul><p>Depending on the question, an answer might come back as plain text, a data table, or a chart — whichever fits best. Answers involving specific numbers are always pulled directly from your actual data, not guessed at.</p><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p>Once you&#39;re comfortable with the basics, explore the rest of the docs — starting with <a href="/docs/concepts/projects">Concepts</a> if you want to understand how OrbySystems is put together, or <a href="/docs/personal-finance/types-of-finance-projects">Personal Finance</a> if you&#39;re focused on financial tracking.</p>',9)])])}const y=e(n,[["render",r]]);export{h as __pageData,y as default};
